"use client";

import Image from "next/image";
import { useEffect, useState } from "react";

export default function Hero() {
  const [animate, setAnimate] = useState(false);

  useEffect(() => {
    setAnimate(true); // trigger animation on load (mobile-friendly)
  }, []);

  const flower =
    "https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199688/homeheroflower_l0owlr.webp";
  const person =
    "https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199689/person_isbwyu.webp";
  const splash =
    "https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199690/splash_z7aa5q.png";

  return (
    <section className="relative flex min-h-[85vh] w-full items-center justify-center overflow-hidden bg-white px-4">

      {/* 🌸 Top Left */}
      <Image
        src={flower}
        alt="flower"
        width={600}
        height={600}
        priority
        className={`
          absolute top-0 left-0
          w-[10rem] sm:w-[14rem] lg:w-[30rem]

          -mt-6 -ml-4 sm:-mt-10 sm:-ml-6 lg:-mt-[120px] lg:-ml-[40px]

          transition-all duration-700 ease-in-out
          ${animate ? "translate-x-0 translate-y-0 opacity-100" : "translate-x-[40%] translate-y-[40%] opacity-0"}
        `}
      />

      {/* 🌸 Top Right */}
      <Image
        src={flower}
        alt="flower"
        width={600}
        height={600}
        priority
        className={`
          absolute top-0 right-0
          w-[10rem] sm:w-[14rem] lg:w-[30rem]

          -mt-6 -mr-4 sm:-mt-10 sm:-mr-6 lg:-mt-[110px] lg:-mr-[50px]

          transition-all duration-700 ease-in-out
          ${animate ? "translate-x-0 translate-y-0 opacity-100" : "-translate-x-[40%] translate-y-[40%] opacity-0"}
        `}
      />

      {/* 🌸 Bottom Left */}
      <Image
        src={flower}
        alt="flower"
        width={600}
        height={600}
        className={`
          absolute bottom-0 left-0
          w-[10rem] sm:w-[14rem] lg:w-[30rem]

          -mb-6 -ml-4 sm:-mb-10 sm:-ml-6 lg:-mb-[100px] lg:-ml-[100px]

          scale-x-[-1]

          transition-all duration-700 ease-in-out
          ${animate ? "translate-x-0 translate-y-0 opacity-100" : "translate-x-[40%] -translate-y-[40%] opacity-0"}
        `}
      />

      {/* 🌸 Bottom Right */}
      <Image
        src={flower}
        alt="flower"
        width={600}
        height={600}
        className={`
          absolute bottom-0 right-0
          w-[10rem] sm:w-[14rem] lg:w-[30rem]

          -mb-6 -mr-4 sm:-mb-10 sm:-mr-6 lg:-mb-[100px] lg:-mr-[60px]

          scale-x-[-1]

          transition-all duration-700 ease-in-out
          ${animate ? "translate-x-0 translate-y-0 opacity-100" : "-translate-x-[40%] -translate-y-[40%] opacity-0"}
        `}
      />

      {/* 👤 Person */}
      <div
        className={`
          relative z-10 flex items-center justify-center

          w-[16rem] sm:w-[20rem] lg:w-[24rem]

          transition-all duration-700 ease-out
          ${animate ? "scale-100 opacity-100" : "scale-90 opacity-0"}
        `}
        style={{
          backgroundImage: `url(${splash})`,
          backgroundRepeat: "no-repeat",
          backgroundPosition: "center",
          backgroundSize: "contain",
        }}
      >
        <Image
          src={person}
          alt="person"
          width={400}
          height={400}
          priority
          className="w-full h-auto"
        />
      </div>
    </section>
  );
}